def bounding_box_fill(grid: List[List[int]]) -> List[List[int]]:
    """Fill the bounding box of 4s with 4s"""
    h, w = len(grid), len(grid[0]) if grid else 0
    if h == 0:
        return grid

    # Find bounding box of 4s
    min_r, max_r = h, -1
    min_c, max_c = w, -1

    has_4 = False
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 4:
                has_4 = True
                if r < min_r: min_r = r
                if r > max_r: max_r = r
                if c < min_c: min_c = c
